void playSoundButton(){
  digitalWrite(buzzer,HIGH);
  delay(10);
  if(buzzerState==HIGH){digitalWrite(buzzer,HIGH);}
  if(buzzerState==LOW){digitalWrite(buzzer,LOW);}
}

void playSoundSelect(){
  digitalWrite(buzzer,HIGH);
  delay(4);
  digitalWrite(buzzer,LOW);
}

int buttonCheck(){
  buttonNew = digitalRead(buttonPin);
  if(buttonOld==1 && buttonNew==0){
    bCounter++;
    playSoundButton();
  }
  buttonOld = buttonNew;
  delay(50);
  return bCounter;
}

int squareCheck(){
  squareNew = digitalRead(squarePin);
  if(squareOld==1 && squareNew==0){
    sCounter++;
    playSoundButton();
  }
  squareOld = squareNew;
  delay(50);
  return sCounter;
}

int circleCheck(){
  circleNew = digitalRead(circlePin);
  if(circleOld==1 && circleNew==0){
    cCounter++;
    playSoundButton();
  }
  circleOld = circleNew;
  delay(50);
  return cCounter;
}

int selection(){
  int x = analogRead(selectPin);
  return x;
}

void playSoundWin(){
  for(int i=1; i<=10; i++){
  digitalWrite(buzzer,HIGH);
  digitalWrite(LED,HIGH);
  delay(20);
  digitalWrite(buzzer,LOW);
  digitalWrite(LED,LOW);
  delay(40);
  }
}

void playSoundLose(){
  for(int i=1; i<=10; i++){
  digitalWrite(buzzer,HIGH);
  delay(20);
  digitalWrite(buzzer,LOW);
  delay(160);
  }
}

void playSoundDraw(){
  for(int i=1; i<=10; i++){
  digitalWrite(buzzer,HIGH);
  delay(40);
  digitalWrite(buzzer,LOW);
  delay(20);
  }
}

void rpsAnimate(){
  for(int i = 1; i<=(random(5,11)); i++){
    oled.clearDisplay();
    oled.drawBitmap(0,0,rock2,128,64,SH110X_WHITE);
    oled.display();
    delay(100);
    oled.clearDisplay();
    oled.drawBitmap(0,0,paper2,128,64,SH110X_WHITE);
    oled.display();
    delay(100);
    oled.clearDisplay();
    oled.drawBitmap(0,0,scissors2,128,64,SH110X_WHITE);
    oled.display();
    delay(100);
  }
}

